def fit_scale(train):
    if not train:
        raise ValueError('training values required')
    mean = sum(train) / len(train)
    scale = (sum((x - mean) ** 2 for x in train) / len(train)) ** 0.5
    return mean, scale or 1.0

def transform(values, mean, scale):
    return [(x - mean) / scale for x in values]

