def log_loss(labels, probabilities):
    import math
    if not labels:
        raise ValueError('labels required')
    total = 0.0
    for label, probability in zip(labels, probabilities):
        p = min(1 - 1e-12, max(1e-12, probability))
        total -= label * math.log(p) + (1 - label) * math.log1p(-p)
    return total / len(labels)

