def nearest_label(points, labels, query, k):
    if k <= 0 or not points:
        raise ValueError('training data and positive k required')
    order = sorted(range(len(points)), key=lambda i: sum((a-b)**2 for a,b in zip(points[i], query)))
    counts = {}
    for i in order[:k]:
        counts[labels[i]] = counts.get(labels[i], 0) + 1
    return min(counts, key=lambda label: (-counts[label], label))

