def split_gini(values, labels, threshold):
    if not labels:
        return 0.0
    groups = [[], []]
    for value,label in zip(values, labels):
        groups[0 if value < threshold else 1].append(label)
    score = 0.0
    for group in groups:
        if not group:
            continue
        counts = {}
        for label in group:
            counts[label] = counts.get(label,0) + 1
        impurity = 1 - sum((n/len(group))**2 for n in counts.values())
        score += len(group)/len(labels) * impurity
    return score

def folds(n, k):
    if k < 2 or n < k:
        raise ValueError('require n >= k >= 2')
    return [([i for i in range(n) if i % k != f], [i for i in range(n) if i % k == f]) for f in range(k)]

