def stop_epoch(losses, patience, min_delta=0.0):
    if patience <= 0 or min_delta < 0:
        raise ValueError('invalid stopping policy')
    best = None
    stale = 0
    for epoch,loss in enumerate(losses):
        if best is None or loss < best - min_delta:
            best, stale = loss, 0
        else:
            stale += 1
            if stale >= patience:
                return epoch
    return None

